        exam: [.direct("What did {D} say at your door?", "\"That federal money would cover the repairs after the hurricane. {D} had a clipboard and a card and a truck with a sign.\""), .direct("What damage did you have?", "\"The storm tore off part of my roof. Water poured into my bedroom, and I had nowhere to go.\""), .direct("How much did you pay?", "\"$9,000, as a deposit. I wrote a check right there because {D} said the crew would start the next week.\""), .direct("Was a contract signed?", "\"Yes. It was a short form with a price and a start date. I signed it at my kitchen table.\""), .direct("Was any work done?", "\"None. No crew came, no materials arrived, and {D} stopped answering my calls.\""), .direct("How did you feel when you learned of the others?", "\"Sick. I learned that dozens of other homeowners had paid, and I was one of many.\""), .cross("Did {D} seem professional?", "\"Yes. {D} was polite, had a card and a clipboard, and answered my questions.\""), .cross("Did {D} say anything about a license?", "\"Not that I remember. I did not ask, and I wish I had.\""), .cross("Did you check the sign on the truck?", "\"I read it. It said federal approval, and I took that as a good sign.\""), .cross("Did you get any money back?", "\"No. {D} offered nothing, and I am still waiting.\""), .cross("Have you spoken to other homeowners?", "\"A few. Their stories are all similar, and we are angry.\"")],
        theory: ("{D} took storm-damaged homeowners' deposits.", "A contractor delayed by supply shortages."),
