        state: [E(.video, 3, "Hallway Camera", "{D} sits outside the door for five hours."), E(.document, 3, "Written Notice", "Delivered to {D}; a signed return receipt."), E(.statement, 2, "Property Manager", "Confirms the notice was posted at the desk."), E(.digital, 1, "Texts", "{V} asked {D} twice to stop contacting {V.him}.")],
        defense: [E(.statement, 1, "A Gift", "{DL} says {D.he} meant to leave a gift and go."), E(.statement, 1, "Locked Door", "The side entrance was propped open.")],
        role: "Property manager",
