        timeline: [(-60, "The notice is delivered."), (0, "12:45 a.m.: {D} enters the side door."), (0, "1:10 a.m.: {D} knocks once."), (0, "6:15 a.m.: {V} calls the property manager."), (0, "6:40 a.m.: deputies arrive.")],
        identified: "A hallway camera.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let pawnToolsV1 = SmallCases.make(
