        state: [E(.physical, 3, "Engraved Tools", "Eleven tools with {V}'s engraving."), E(.document, 3, "Shop Ticket", "{D} paid $200 for tools worth $3,500."), E(.document, 2, "Seller ID", "The same seller sold tools from another theft.")],
        defense: [E(.statement, 2, "ID Check", "{DL} says the seller showed an ID.")],
        role: "Contractor",
        exam: [.direct("What did you see on the pawn shop shelf?", "\"Eleven of my engraved tools. I recognized them at once, from my engraving and from the way I wear a handle.\""), .direct("How had they been taken from you?", "\"My trailer had been broken into the day before. Tools worth thousands were gone, and I filed a report.\""), .direct("How did they reach the shop?", "\"Sold to the shop. The shop's records show {D}, the owner, bought them from one seller the day after the theft.\""), .direct("What did the shop ticket say?", "\"{D} paid $200 for tools worth $3,500. The price is a small fraction of what the tools cost new.\""), .direct("Was there an ID?", "\"Yes. The seller showed an ID, and the shop copied it. I have seen the copy.\""), .direct("Was the price low?", "\"Very. I could not believe it when I saw the number on the ticket.\""), .cross("Did you see {D} buy the tools?", "\"No. I only saw them on the shelf and read the records afterward.\""), .cross("Is the engraving easy to see?", "\"Fairly. It is on the metal near the handle, and someone who looked would notice.\""), .cross("Did {D} cooperate when you came in?", "\"Yes. {D} pulled the records and called the deputies without argument.\""), .cross("Did the seller come from another theft?", "\"The seller's ID appears in another theft report, as I understand it.\""), .cross("Did {D} offer to return the tools?", "\"Yes. {D} said the tools could be released once the deputies cleared it.\"")],
        theory: ("{D} bought tools that {D.he} should have known were stolen.", "A pawnbroker who checked an ID."),
        allocution: "\"I'm sorry. It won't happen again.\"",
        truths: ("{DL} had bought tools from this seller before.", "{DL} paid a tenth of the value."),
        defendant: [.direct("Did you know the tools were stolen?", "\"No. I had no idea. The seller showed an ID and told me the tools were from a job that had ended.\""), .direct("Why were the tools so cheap?", "\"The seller needed money. People sell tools at a loss all the time, and a pawn shop is a place to get quick cash.\""), .direct("What checks did you make?", "\"I looked at the ID and copied it. I wrote down the tools and the amount on the ticket.\""), .direct("Did you see the engraving?", "\"I did not see it. I looked at the condition and the brand, and I did not turn each tool over.\""), .direct("What did you do when {V} came in?", "\"I pulled the records and called the sheriff. I wanted it cleaned up right away.\""), .direct("What do you want {V} to know?", "\"I am so sorry. I did not know, and I will cooperate until you get your tools back.\""), .cross("You paid $200 for tools worth $3,500, didn't you?", "\"Yes. It was a low price. The seller seemed desperate, and I did not push back.\""), .cross("Eleven tools with a contractor's engraving, and you saw nothing?", "\"I did not look closely. That was careless.\""), .cross("The seller's ID is tied to another theft, isn't it?", "\"I only learned that afterward, from the deputies.\""), .cross("A pawn shop owner should check for stolen goods, shouldn't one?", "\"Yes, and I did what I do for every sale. I wish I had done more.\""), .cross("You did not ask where the tools came from, did you?", "\"The seller said a job. I took that as an answer.\"")],
        openings: ("{V}, a contractor whose trailer had been broken into, walked into a pawn shop and found eleven of {V.his} engraved tools on the shelf. The shop's records show {D}, the owner, bought them for $200 the day after the theft from a seller who had been in other theft reports.", "The seller showed identification, and {D} copied it. A pawn shop owner who is shown an ID and a story has no reason to doubt it, and {D} called deputies as soon as {V} came in."),
        closings: ("Eleven engraved tools, a $200 ticket for $3,500 in goods, and a seller tied to another theft. {D} bought them cheap and looked away.", "An ID, a ticket, and a shop owner who called the sheriff when {V} walked in. The State must prove {D} knew the tools were stolen, and the paperwork says {D} did what was asked."),
        timeline: [(-8, "The break-in."), (-7, "The tools are pawned."), (0, "{V} finds them."), (2, "A deputy takes the ticket.")],
        identified: "A pawn ticket.",
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let deletedFootageV1 = SmallCases.make(
        key: "story.deletedFootage",
        category: .publicOrder,
