        state: [E(.digital, 3, "Gate Log", "{D}'s code entered twice overnight."), E(.video, 1, "Facility Camera", "A pickup near unit row C."), E(.physical, 1, "Bolt Cutters", "Found in {D}'s truck.")],
        defense: [E(.statement, 1, "Moving Out", "{DL} says {D.he} was moving out of a unit.")],
        role: "Storage tenant",
        exam: [.direct("Tell the jury about your unit at the storage facility.", "\"I rent a unit to store my electronics and a generator. I use them for my business, and I keep the unit locked with my own padlock.\""), .direct("What did you find on {DATE}?", "\"My unit had been opened with bolt cutters or tools, and my electronics and generator were gone. Nine units had been opened that night.\""), .direct("What did the facility's records show?", "\"The gate keypad log shows {D}'s personal code entered at 1:12 a.m. and again at 3:40 a.m. No other code was used at those times.\""), .direct("What did the facility camera show?", "\"A pickup near unit row C. The camera does not show faces, but it shows a pickup parked near the row where my unit was.\""), .direct("What was found in {D}'s truck?", "\"Bolt cutters. They were found in {D}'s truck when deputies stopped it, and they match the cut marks on several locks.\""), .direct("How did you find out about the generator?", "\"It was listed online a few days later. The listing matched my generator, and I called deputies.\""), .cross("Did you see {D} take anything?", "\"No. I was not there. I only know what the logs and the camera show, and I did not see anyone in the facility.\""), .cross("Did {D} have a unit at the facility?", "\"Yes. {D} says {D} was moving out of a unit. But I understand that {D} had no unit open that week.\""), .cross("Can you read the pickup's plate?", "\"No. The camera shows a pickup but not a plate. I cannot say it was {D}'s truck.\""), .cross("Are bolt cutters common in trucks?", "\"Yes. Many people carry them for work. I do not know how many pickups in the area have them.\""), .cross("Could someone else have used {D}'s code?", "\"I do not know. {D} may have shared the code. I only know that the code was entered twice.\"")],
        theory: ("{D} used a code to break into nine units.", "A tenant moving {D.his} own things."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} had no unit open that week.", "The generator was listed online."),
        defendant: [.direct("Tell us what you were doing at the facility.", "\"I was moving my own belongings out of a unit. I went at night because I work during the day, and it was easier to avoid traffic.\""), .direct("Why did you enter your code twice?", "\"I came once to load and again to finish. I was there at about 1:12 and again at 3:40, and I left after the second trip.\""), .direct("Did you break into any units?", "\"No. I did not. I never touched any lock that was not mine, and I did not take anything that was not mine.\""), .direct("Why were bolt cutters in your truck?", "\"I use them for work. They are a tool I carry in the truck for many jobs, and they are not used on locks at the facility.\""), .direct("What about the generator listed online?", "\"It was not mine to list. I do not know who listed it. I did not sell any generator, and I have never seen it.\""), .direct("Looking back, how do you feel about being accused?", "\"Mostly I feel upset. I was moving my own things, and now I am accused of robbing neighbors. I did not do it.\""), .cross("You had no unit open that week, did you?", "\"I was moving out. I know that makes it look strange, but I was at the facility for my own things.\""), .cross("Your code was entered at 1:12 and again at 3:40, wasn't it?", "\"Yes. That is when I was there. I know the times are late, but I work days.\""), .cross("Bolt cutters were in your truck, weren't they?", "\"Yes. I use them for work. I did not use them at the facility.\""), .cross("A pickup was on camera near unit row C, wasn't it?", "\"Yes. It could have been mine. Many pickups look alike, and I was near that row.\""), .cross("Nine units were opened that night, weren't they?", "\"The facility says so. I did not open any of them. I only opened my own.\"")],
