        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let alibiWitnessV1 = SmallCases.make(
        key: "story.alibiWitness",
        category: .publicOrder,
        headlines: ["Co-Worker Swore Under Oath Colleague Was on Overnight Shift During Hit-and-Run, Time Clock Says Otherwise", "Badge Logs Show Early Departure at 9:40 p.m."],
        law: "perjury",
        threshold: 6,
        spec: "Willfully and falsely testified under oath, in a material matter, that a co-worker was at work all night when a hit-and-run happened.",
        ages: 22...40,
        victim: false,
        summary: "A driver was tried for a hit-and-run that killed a cyclist. {D}, a co-worker, testified under oath that the driver was on the overnight shift at a distribution center from 7 p.m. to 7 a.m. The jury hung. Before the retrial, investigators pulled badge logs showing the driver left at 9:40 p.m., an hour before the crash. {D} is now charged with perjury. {DL} says {D.he} mixed up the night and was not coached.",
        state: [E(.document, 3, "Badge Logs", "The co-worker leaves at 9:40 p.m."), E(.document, 3, "Trial Transcript", "{D} swears the co-worker was there all night."), E(.digital, 2, "Jail Calls", "{D} and the driver discuss 'covering'."), E(.document, 1, "Shift Roster", "{D} and the driver on the same shift.")],
        defense: [E(.statement, 1, "Mixed Up Night", "{DL} says {D.he} confused the night."), E(.statement, 1, "Long Shifts", "{DL} was working long shifts that week.")],
        role: "Detective",
        exam: [.direct("Describe your work as a detective.", "\"I investigate perjury and obstruction cases. I review court transcripts, records, and recordings to find where sworn testimony does not match the evidence.\""), .direct("What happened at the driver's trial?", "\"A driver was tried for a hit-and-run that killed a cyclist. {D}, a coworker, testified under oath that the driver was on the overnight shift from 7 p.m. to 7 a.m.\""), .direct("What happened with the jury?", "\"It hung. The jury could not agree, and the case was set for a retrial.\""), .direct("What did you find before the retrial?", "\"Badge logs show the driver left at 9:40 p.m., about an hour before the crash. That contradicts {D}'s testimony that the driver was there all night.\""), .direct("What did the shift roster show?", "\"{D} and the driver were on the same shift. {D} had every chance to know when the driver left.\""), .direct("What did the jail calls show?", "\"{D} and the driver discussed covering. I considered those calls as evidence of what {D} understood about the testimony.\""), .cross("Did {D} say {D} mixed up the night?", "\"Yes. {D} says {D} confused the night, and was working long shifts that week.\""), .cross("Was {D} coached?", "\"{D} says no. The driver's lawyer told {D} what to expect on cross, but I cannot show {D} was told what to say.\""), .cross("Did {D} testify with notes?", "\"No. {D} testified without notes, relying on memory. That can lead to mistakes.\""), .cross("Do the badge logs show the driver left?", "\"Yes. The logs show a badge swipe at 9:40 p.m. That is an hour before the crash, as the logs show.\""), .cross("Could a person forget which night a coworker left?", "\"It is possible, especially with long shifts. I cannot say what {D} remembered, and I cannot read {D}'s mind.\"")],
        theory: ("{D} lied under oath to give a co-worker an alibi.", "A witness who mixed up a night."),
        allocution: "\"I let things get out of hand.\"",
        truths: ("{DL} had been told by the driver's lawyer what to expect on cross.", "{DL} had testified without notes."),
        defendant: [.direct("Tell the jury about your job and your coworker.", "\"I work at a distribution center on the overnight shift. The driver is a coworker, and I like the driver. We often work the same hours.\""), .direct("What did you say at the trial?", "\"I said the driver was on the overnight shift from 7 p.m. to 7 a.m. I said that because that is what I believed.\""), .direct("Why did you say that?", "\"I confused the night. I was working long shifts that week, and the nights ran together in my memory.\""), .direct("Did anyone tell you what to say?", "\"No. No one coached me. The driver's lawyer told me what to expect on cross, but not what to say.\""), .direct("What did you mean on the jail calls?", "\"I said covering. I meant covering shifts, as coworkers do. I did not mean covering up anything.\""), .direct("How do you feel about being charged?", "\"I would say I feel awful. I did not mean to lie. I made a mistake, and I did not know it would matter so much.\""), .cross("You swore the driver was there all night, didn't you?", "\"Yes. I did. I believed it. I now know the badge logs say otherwise.\""), .cross("The badge logs show the driver left at 9:40, don't they?", "\"Yes. That is what they show. I did not know that when I testified, and I was wrong.\""), .cross("You discussed covering on the jail calls, didn't you?", "\"Yes. I used that word. I meant covering shifts, and I know it sounds bad.\""), .cross("You were on the same shift as the driver, weren't you?", "\"Yes. But we did not always see each other. The center is large.\""), .cross("You testified without notes, didn't you?", "\"Yes. I relied on memory. I should have checked the schedule, and I did not.\"")],
        openings: ("A driver was tried for a hit-and-run that killed a cyclist, and {D}, a coworker, swore the driver was on the overnight shift from 7 p.m. to 7 a.m. The jury hung, and badge logs later showed the driver left at 9:40 p.m., an hour before the crash.", "The defense will present a coworker who confused the night after long shifts, who testified without notes, and who was not coached. A mistaken memory is not perjury."),
        closings: ("A sworn statement that the driver was there all night, badge logs that show the driver left at 9:40, a shared shift roster, and jail calls about covering. The testimony was false.", "A coworker who confused the night after long shifts and testified from memory. The State must prove that {D} knew the testimony was false, and a mistake is not a lie."),
        timeline: [(-365, "The hit-and-run."), (-300, "{D} testifies."), (-30, "Investigators pull the badge logs."), (0, "{D} is charged with perjury."), (14, "The jail calls are produced.")],
        identified: "Badge logs.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let plannedPharmacyRobberyV1 = SmallCases.make(
