        state: [E(.digital, 3, "Group Chat", "{D} gives the time, the door and the masks."), E(.statement, 3, "Informant", "Was in the chat and brought it to deputies."), E(.physical, 2, "Car Search", "Two masks and a pellet gun in the trunk."), E(.document, 1, "Receipt", "Ski masks bought the day before.")],
        defense: [E(.statement, 1, "Just Talk", "{DL} says nobody meant to do it."), E(.statement, 1, "Pellet Gun", "The pellet gun was for rabbits.")],
        role: "Sheriff's detective",
        exam: [.direct("What do you do as a sheriff's detective?", "\"I investigate robberies and conspiracies. I work with informants, review messages, and make arrests when people plan violent crimes.\""), .direct("How did this case begin?", "\"A paid informant who was a member of a group chat named after a basketball team brought messages to deputies.\""), .direct("What did the group chat discuss?", "\"For a week, members discussed robbing a check-cashing store on payday. {D} wrote when the armored van left, which door to use, and that masks and a pistol were bought.\""), .direct("What did {D} write about the masks?", "\"{D} wrote masks tomorrow. A receipt shows ski masks were bought the day before the arrest.\""), .direct("What happened on the night of the arrest?", "\"Officers arrested {D} and another member the night before the planned robbery. We found two ski masks and a pellet gun in the trunk.\""), .direct("What did you learn about {D}'s movements?", "\"{D} drove past the store twice that week. I noted that as part of how the group looked at the target.\""), .cross("Was anything stolen?", "\"No. The robbery never took place. We arrested {D} before it could happen.\""), .cross("What did {D} say about the chat?", "\"{D} says it was talk and a joke between friends. I cannot say what {D} truly intended.\""), .cross("What was the pellet gun for?", "\"{D} says it was for rabbits. A pellet gun is not a firearm, and I did not find a real pistol.\""), .cross("Did the informant have a reason to push the plan?", "\"The informant was paid, which is a reason to produce evidence. I did not see the informant urging anyone, but I cannot rule it out.\""), .cross("Did {D} say anything to deputies when arrested?", "\"{D} said it was a joke. {D} did not try to run, and cooperated with the arrest.\"")],
        theory: ("{D} planned a robbery and took steps toward it.", "Friends talking big."),
        allocution: "\"I scared someone badly, and I'm sorry.\"",
        truths: ("{DL} drove past the store twice that week.", "{DL} bought the masks after writing 'masks tomorrow'."),
        defendant: [.direct("Tell us about the group chat.", "\"It was a chat among friends named after a basketball team. We joked a lot, and I wrote things I did not mean.\""), .direct("Why did you write about the armored van and the door?", "\"It was talk. We were joking about what it would be like to rob a store. Nobody meant to do it.\""), .direct("Why did you buy ski masks?", "\"It was cold. I wanted them for winter, and I bought them the day before. I did not buy them to rob anyone.\""), .direct("What was the pellet gun for?", "\"Rabbits. I have used it to shoot at pests near my house. It was in the trunk because I was going to a friend's place.\""), .direct("Why did you drive past the store twice?", "\"It is on my way. I live near there, and I pass it often. I did not drive past to watch the store.\""), .direct("How do you feel about being charged?", "\"If I am honest, I feel stupid and scared. I wrote things I should not have, and now a joke has become a case.\""), .cross("You wrote when the armored van left, didn't you?", "\"Yes. I wrote it. I was repeating what I had heard, and I did not mean it as a plan.\""), .cross("You wrote masks tomorrow, didn't you?", "\"Yes. I did. It was a joke, but I understand how it looks.\""), .cross("You bought two ski masks the day before, didn't you?", "\"Yes. I did. It was a coincidence, and I know it is a bad one.\""), .cross("A pellet gun was in your trunk, wasn't it?", "\"Yes. It is for rabbits. I know it looks like a robbery kit, and I understand why.\""), .cross("Nobody meant to do it, did they?", "\"That is what I believe. I know the jury may not believe me, but it is the truth.\"")],
        openings: ("For a week, a group chat named after a basketball team discussed robbing a check-cashing store on payday. {D} wrote when the armored van left, which door to use, and that masks and a pistol were bought, and officers arrested {D} with masks and a pellet gun in the car.", "The defense will present talk and jokes between friends, masks bought for the cold, and a pellet gun used for rabbits. Words in a chat are not a plan carried out."),
        closings: ("A chat that gave the time, the door, and the masks, a receipt for ski masks, and two masks and a pellet gun in the trunk. The plan was real, and {D} took part.", "A chat full of jokes among friends, a pellet gun for rabbits, and masks bought for the cold. The State has not proved that {D} agreed to a real robbery."),
        timeline: [(-7, "The chat starts."), (-3, "{D} writes about the van."), (-1, "{D} buys masks."), (0, "The night of the arrest."), (1, "The informant's messages are entered.")],
        identified: "An informant's messages.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof", "hearsay"],
        genders: ["D": .male])

